    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If the object does not expose an internal mapping, raise an error
    if not hasattr(self, "_items"):
        raise AttributeError("The object has no '_items' attribute")

    # If no keys are supplied, return all values
    if not keys:
        if hasattr(self._items, "values"):
            return list(self._items.values())
        else:
            # Assume a sequence
            return list(self._items)

    # Prepare a list of all values for index-based access
    all_values = list(self._items.values()) if hasattr(self._items, "values") else list(self._items)

    result = []
    for key in keys:
        if isinstance(key, int):
            # Index-based lookup
            if 0 <= key < len(all_values):
                result.append(all_values[key])
        else:
            # Key-based lookup
