def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    namespace = {}
    # Use __slots__ to restrict attributes to the given fields
    namespace['__slots__'] = tuple(fields)
    # Store the SRID mapping as a class attribute
    namespace['_srid_map'] = srid_map

    def __init__(self, *args, **kwargs):
        if len(args) > len(fields):
            raise TypeError(f"Expected at most {len(fields)} arguments")
        # Assign positional arguments
        for key, value in zip(fields, args):
            setattr(self, key, value)
        # Assign remaining fields from keyword arguments or default to None
        for key in fields[len(args):]:
            if key in kwargs:
                setattr(self, key, kwargs.pop(key))
            else:
                setattr(self, key, None)
        if kwargs:
            raise TypeError(f"Unexpected keyword arguments: {', '.join(kwargs)}")

    namespace['__init__'] = __init__
    # Create and return the new subclass of Point
    return type(name, (Point,), namespace)

