def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Return precomputed indices if available
    if hasattr(self, "_err_indices") and coord_name in self._err_indices:
        return self._err_indices[coord_name]
    # Attempt to compute from an error array stored in self.errors
    err_arr = getattr(self, "errors", {}).get(coord_name)
    if err_arr is None:
        return np.array([], dtype=int)
    arr = np.asarray(err_arr)
    # For numeric arrays, return indices where value is non‑zero
    if arr.dtype.kind in ("f", "i", "u"):
        return np.where(arr != 0)[0]
    # For boolean arrays, return indices where True
    if arr.dtype.kind == "b":
        return np.where(arr)[0]
    # Fallback: return all indices
    return np.arange(arr.size)

