def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}
    for logical_path, data in inventory.items():
        content_files = set()
        # Handle mapping of version -> content_file
        if isinstance(data, dict):
            if version in data:
                content_files.add(data[version])
        # Handle list of items (could be tuples or dicts)
        elif isinstance(data, list):
            for item in data:
                if isinstance(item, dict):
                    if item.get("version") == version:
                        cf = item.get("content_file") or item.get("file")
                        if cf:
                            content_files.add(cf)
                elif isinstance(item, tuple) and len(item) == 2:
                    v, cf = item
                    if v == version:
                        content_files.add(cf)
        # If data is a set or other iterable of content files, include all
        elif isinstance(data, set):
            content_files.update(data)
        # If data is a single content file string, include it if version matches
        elif isinstance(data, str):
            # Assume single file for all versions
            content_files.add(data)
        if content_files:
            path_map[logical_path] = content_files
    return path_map

