def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    base_indent = ' ' * indent

    def _format(obj, level=0):
        prefix = base_indent + ' ' * (level * 2)
        if isinstance(obj, dict):
            items = []
            for k, v in sorted(obj.items(), key=lambda x: str(x)):
                items.append(f"{prefix}{k!r}: {_format(v, level + 1)}")
            return "{\n" + ",\n".join(items) + f"\n{base_indent}}}"
        elif isinstance(obj, (list, tuple, set)):
            cls_name = type(obj).__name__
            items = [f"{prefix}{_format(v, level + 1)}" for v in obj]
            return f"{cls_name}([\n" + ",\n".join(items) + f"\n{base_indent}])"
        elif hasattr(obj, "__dict__"):
            attrs = {k: v for k, v in obj.__dict__.items() if not k.startswith('_')}
            return _format(attrs, level)
        else:
            return repr(obj)

    header = f"{self.__class__.__name__} at {hex(id(self))}" if debug else ""
    body = _format(self, 0)
    return f"{header}\n{body}" if header else body

