def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    # Attributes that can be fractional
    attrs = ['years', 'months', 'days', 'weeks', 'hours', 'minutes', 'seconds', 'microseconds']
    values = {a: getattr(self, a) for a in attrs}

    # Convert fractional parts to the next smaller unit
    for a in ['days', 'hours', 'minutes', 'seconds']:
        v = values[a]
        if isinstance(v, float) and not v.is_integer():
            whole = int(v)
            frac = v - whole
            values[a] = whole
            if a == 'days':
                values['hours'] += int(round(frac * 24))
            elif a == 'hours':
                values['minutes'] += int(round(frac * 60))
            elif a == 'minutes':
                values['seconds'] += int(round(frac * 60))
            elif a == 'seconds':
                values['microseconds'] += int(round(frac * 1_000_000))

    # Ensure all values are integers
    for a in attrs:
        values[a] = int(values[a])

    return relativedelta(**values)

