def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces:
        return ''
    # Convert all pieces to strings for safe concatenation
    str_pieces = [str(p) for p in pieces]
    if style == 'short':
        # major.minor
        return '.'.join(str_pieces[:2])
    elif style == 'full':
        # major.minor.patch[.build]
        return '.'.join(str_pieces)
    elif style == 'semantic':
        # major.minor.patch[-suffix]
        if len(str_pieces) > 3:
            base = '.'.join(str_pieces[:3])
            suffix = str_pieces[3]
            return f"{base}-{suffix}"
        else:
            return '.'.join(str_pieces)
    elif style == 'compact':
        # majorminorpatch concatenated
        return ''.join(str_pieces)
    else:
        raise ValueError(f"Unsupported style: {style}")

