def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Attempt to retrieve all objects in the hierarchy.  The concrete
    # implementation is expected to provide a method named
    # ``_get_all_objects`` or ``objects`` that yields the objects to
    # validate.  If neither is available we simply return zeros.
    try:
        objects_iter = getattr(self, "_get_all_objects", None)
        if objects_iter is None:
            objects_iter = getattr(self, "objects", None)
        if objects_iter is None:
            raise AttributeError
        objects = objects_iter()
    except Exception:
        # No objects to validate
        return 0, 0

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        valid = True

        if validate_objects:
            try:
                # The concrete implementation should provide a method
                # named ``_validate_object`` that raises an exception on
                # failure.
                validate_fn = getattr(self, "_validate_object", None)
                if validate_fn is None:
                    raise AttributeError
                validate_fn(obj)
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Validation warning for object {obj!r}: {e}")

        if check_digests and valid:
            try:
                # The concrete implementation should provide a method
                # named ``_check_digest`` that raises an exception on
                # failure.
                digest_fn = getattr(self, "_check_digest", None)
                if digest_fn is None:
                    raise AttributeError
                digest_fn(obj)
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Digest warning for object {obj!r}: {e}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

