def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a root inventory to compare against
    if not hasattr(self, "root_inventory") or self.root_inventory is None:
        raise ValueError("root_inventory must be set before validating version inventories")

    # Containers for the inventories and any digest mismatches
    self.version_inventories = {}
    self.different_digests = {}

    root_inv = self.root_inventory

    for ver_dir in version_dirs:
        # Expect an inventory file named 'inventory.json' inside each version directory
        inv_path = os.path.join(ver_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file in version directory '{ver_dir}'")

        with open(inv_path, "r", encoding="utf-8") as f:
            try:
                inv = json.load(f)
            except Exception as exc:
                raise ValueError(f"Failed to parse inventory in '{ver_dir}': {exc}")

        # Store the inventory for later use
        self.version_inventories[ver_dir] = inv

        # Verify that the inventory contains all items that exist in the root inventory
        missing_items = set(root_inv) - set(inv)
        if missing_items:
            raise ValueError(
                f"Inventory in '{ver_dir}' is missing items present in the root inventory: "
                f"{', '.join(sorted(missing_items))}"
            )

        # Record any digest differences between this version and the root inventory
        for path, digest in inv.items():
            root_digest = root_inv.get(path)
            if root_digest is not None and digest != root_digest:
                self.different_digests.setdefault(path, []).append((ver_dir, digest))
    return self.version_inventories

