                raw = fd.read()
            if filename.lower().endswith('.toml'):
                cfg = toml.loads(raw)
            elif filename.lower().endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            elif filename.lower().endswith('.json'):
                cfg = json.loads(raw)
            else:
                # Unsupported format
                record = logging.LogRecord(
                    name='config_loader',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Unsupported configuration format: {filename}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue

            if resolve_env and isinstance(cfg, dict):
                def _expand(value):
                    if isinstance(value, str):
                        return os.path.expandvars(value)
                    if isinstance(value, dict):
                        return {k: _expand(v) for k, v in value.items()}
                    if isinstance(value, list):
                        return [_expand(v) for v in value]
                    return value
                cfg = _expand(cfg)

            if overrides:
                if isinstance(cfg, dict):
                    cfg.update(overrides)

            config_map[filename] = cfg

        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error parsing configuration file {filename}: {exc}',
                args=(),
                exc_info=(type(exc), exc, exc.__traceback__)
            )
            error_records.append(record)

    return config_map, error_records

