def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Determine if candidate is a class or an instance
    if isinstance(candidate, type):
        # candidate is a class
        if not issubclass(candidate, iface):
            raise TypeError(f"{candidate.__name__} does not subclass {iface.__name__}")
    else:
        # candidate is an instance
        if not isinstance(candidate, iface):
            raise TypeError(f"Instance of {candidate.__class__.__name__} does not implement {iface.__name__}")

    # If tentative, skip detailed attribute checks
    if tentative:
        return

    # Check that all public attributes/methods of iface are present in candidate
    for name in dir(iface):
        if name.startswith('_'):
            continue
        iface_attr = getattr(iface, name)
        if not hasattr(candidate, name):
            raise AttributeError(f"{candidate} is missing attribute '{name}' required by {iface.__name__}")
        cand_attr = getattr(candidate, name)
        # If the interface attribute is callable, ensure the candidate's attribute is also callable
        if callable(iface_attr) and not callable(cand_attr):
            raise TypeError(f"Attribute '{name}' of {candidate} should be callable as defined in {iface.__name__}")
    # All checks passed; candidate is considered a valid implementation of iface.

