def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return {}
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        # The JSON format is already a dict; return it directly
        return data
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        # XRD may use a namespace; handle both namespaced and non‑namespaced tags
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        subject_elem = root.find('Subject') or root.find('xrd:Subject', ns)
        subject = subject_elem.text if subject_elem is not None else None

        links = []
        for link_elem in root.findall('Link') + root.findall('xrd:Link', ns):
            link = {k: v for k, v in link_elem.attrib.items()}
            # Some XRD links may contain nested elements; include them as text if present
            if link_elem.text and link_elem.text.strip():
                link['text'] = link_elem.text.strip()
            links.append(link)

        return {'subject': subject, 'links': links}
    except Exception:
        # If parsing fails, return an empty dict
        return {}

