def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Merge answer file and CLI arguments, giving precedence to CLI
    merged_args = {**answer_file_args, **cli_args}

    # If the instance defines a mapping of deprecated to current arguments,
    # warn about any usage of the deprecated names.
    deprecated_map = getattr(self, "deprecated_args", {})
    for old_name, new_name in deprecated_map.items():
        if old_name in cli_args:
            warnings.warn(
                f"Argument '{old_name}' is deprecated; use '{new_name}' instead.",
                DeprecationWarning,
            )
        if old_name in answer_file_args:
            warnings.warn(
                f"Argument '{old_name}' is deprecated in answer file; use '{new_name}' instead.",
                DeprecationWarning,
            )

    # Additionally, warn about any argument that follows a common
    # deprecation pattern (e.g., starts with 'old_').
    for arg in merged_args:
        if arg.startswith("old_"):
            new_arg = arg[4:]  # strip the 'old_' prefix
            warnings.warn(
                f"Argument '{arg}' is deprecated; use '{new_arg}' instead.",
                DeprecationWarning,
            )

