def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Default bounds defined on the instance
    default_min = getattr(self, 'min_', None)
    default_max = getattr(self, 'max_', None)
    if default_min is None or default_max is None:
        raise AttributeError("Instance must define 'min_' and 'max_' attributes for default bounds")

    # If args is a mapping, validate each value against per-key bounds if present
    if isinstance(args, dict):
        for key, value in args.items():
            min_val = getattr(self, f"min_{key}", default_min)
            max_val = getattr(self, f"max_{key}", default_max)
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument '{key}' with value {value} is out of bounds [{min_val}, {max_val}]"
                )
    else:
        # Assume an iterable of values; use default bounds
        for idx, value in enumerate(args):
            if value < default_min or value > default_max:
                raise ValueError(
                    f"Argument at position {idx} with value {value} is out of bounds [{default_min}, {default_max}]"
                )
    return args

